<?php
require_once __DIR__.'/includes/functions.php';must_login();require_permission('scheduling');check_csrf();require_once __DIR__.'/config/database.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{$esp=(int)($_POST['especialista_id']??0);if(!$esp)throw new RuntimeException('Selecciona un especialista.');$pdo->beginTransaction();$pdo->prepare('DELETE FROM especialista_especialidad WHERE especialista_id=?')->execute([$esp]);$pdo->prepare('DELETE FROM especialista_servicio WHERE especialista_id=?')->execute([$esp]);$a=array_unique(array_map('intval',$_POST['especialidades']??[]));$b=array_unique(array_map('intval',$_POST['servicios']??[]));$ins=$pdo->prepare('INSERT INTO especialista_especialidad(especialista_id,especialidad_id) VALUES(?,?)');foreach($a as $v)$ins->execute([$esp,$v]);$ins=$pdo->prepare('INSERT INTO especialista_servicio(especialista_id,servicio_id) VALUES(?,?)');foreach($b as $v)$ins->execute([$esp,$v]);$pdo->commit();flash('Asignaciones actualizadas.');go('asignaciones.php?especialista_id='.$esp);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'No se pudieron guardar las asignaciones.':$e->getMessage();}
$specs=$pdo->query("SELECT id,nombres,apellidos FROM especialistas WHERE estado='Activo' ORDER BY nombres")->fetchAll();$selected=(int)($_GET['especialista_id']??($_POST['especialista_id']??($specs[0]['id']??0)));$q=$pdo->prepare('SELECT especialidad_id FROM especialista_especialidad WHERE especialista_id=?');$q->execute([$selected]);$selE=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$pdo->prepare('SELECT servicio_id FROM especialista_servicio WHERE especialista_id=?');$q->execute([$selected]);$selS=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$esps=$pdo->query('SELECT id,nombre,descripcion FROM especialidades ORDER BY nombre')->fetchAll();$services=$pdo->query("SELECT id,nombre,precio,duracion_minutos FROM servicios WHERE estado='Activo' ORDER BY nombre")->fetchAll();$title='Asignaciones';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">ADMINISTRACIÓN</span><h1>Especialidades y servicios</h1><p class="muted">Define qué servicios puede realizar cada especialista.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="panel"><form method="get" class="inline-form"><label class="field"><span>Especialista</span><select name="especialista_id" onchange="this.form.submit()"><option value="">Seleccionar</option><?php foreach($specs as $s):?><option value="<?=$s['id']?>" <?=$selected===$s['id']?'selected':''?>><?=e($s['nombres'].' '.$s['apellidos'])?></option><?php endforeach;?></select></label></form><?php if($selected):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="especialista_id" value="<?=$selected?>"><div class="split"><div><h2>Especialidades</h2><?php foreach($esps as $x):?><label class="checkline"><input type="checkbox" name="especialidades[]" value="<?=$x['id']?>" <?=in_array((int)$x['id'],$selE,true)?'checked':''?>> <?=e($x['nombre'])?></label><?php endforeach;?></div><div><h2>Servicios que puede realizar</h2><?php foreach($services as $x):?><label class="checkline"><input type="checkbox" name="servicios[]" value="<?=$x['id']?>" <?=in_array((int)$x['id'],$selS,true)?'checked':''?>> <?=e($x['nombre'].' · '.money($x['precio']).' · '.$x['duracion_minutos'].' min')?></label><?php endforeach;?></div></div><button class="btn">Guardar asignaciones</button></form><?php else:?><p class="empty">Primero registra un especialista activo.</p><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
